// ════════════════════════════════════════════════
// تحويل Markdown → HTML أنيق بدون # و *
// ════════════════════════════════════════════════

const raw = $('AI Agent').item.json.output || '';

function mdToHtml(text) {
  let html = text;

  // ── عناوين ──────────────────────────────────────
  html = html.replace(/^#{4}\s+(.+)$/gm, '<h4>$1</h4>');
  html = html.replace(/^#{3}\s+(.+)$/gm, '<h3>$1</h3>');
  html = html.replace(/^#{2}\s+(.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^#{1}\s+(.+)$/gm, '<h1>$1</h1>');

  // ── خطوط فاصلة ━━━ أو --- ───────────────────────
  html = html.replace(/━+/g, '<hr class="divider">');
  html = html.replace(/^-{3,}$/gm, '<hr class="divider">');

  // ── Bold **text** و __text__ ────────────────────
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/__(.+?)__/g, '<strong>$1</strong>');

  // ── Italic *text* ───────────────────────────────
  html = html.replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '<em>$1</em>');

  // ── قوائم مرقمة 1. ──────────────────────────────
  html = html.replace(/^\d+\.\s+(.+)$/gm, '<li class="numbered">$1</li>');
  html = html.replace(/(<li class="numbered">.*?<\/li>\n?)+/gs, '<ol>$&</ol>');

  // ── قوائم نقطية * أو - ──────────────────────────
  html = html.replace(/^[\*\-]\s+(.+)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>(?!.*class).*?<\/li>\n?)+/gs, '<ul>$&</ul>');

  // ── رموز تعبيرية كعناوين أقسام (📘 📅 ⚡ إلخ) ───
  html = html.replace(/^([📘📅⚡✏️💡🎯📝📚⚠️🔑✅❌🔸🔹➤►•].*?)$/gm, '<div class="section-title">$1</div>');

  // ── فقرات ────────────────────────────────────────
  // فصل الفقرات بسطر فارغ
  html = html.replace(/\n\n+/g, '\n\n');
  const lines = html.split('\n');
  const result = [];
  let inParagraph = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === '') {
      if (inParagraph) { result.push('</p>'); inParagraph = false; }
    } else if (
      line.startsWith('<h') || line.startsWith('<ul') ||
      line.startsWith('<ol') || line.startsWith('<li') ||
      line.startsWith('<hr') || line.startsWith('<div') ||
      line.startsWith('</') 
    ) {
      if (inParagraph) { result.push('</p>'); inParagraph = false; }
      result.push(line);
    } else {
      if (!inParagraph) { result.push('<p>'); inParagraph = true; }
      result.push(line);
    }
  }
  if (inParagraph) result.push('</p>');

  return result.join('\n');
}

const htmlContent = mdToHtml(raw);

return [{ json: { htmlOutput: htmlContent } }];

